        print(candidate)
        break
else:
    raise SystemExit("Unable to locate repo-scoped .codex/hooks.json from hook cwd")'"'"'); printf "%s" "$payload" | "$repo/.codex/hooks/run_python_hook.sh" "$repo/.codex/hooks/session_context.py"'

